    "    emit_iconv_create_warning(ctx, inst, prepend_from_name(inst))?;",
    "    emit_iconv_create_warning(ctx, inst, prepend)?;",
)
s = s.replace(
    """/// Reports whether this instruction is a `stream_filter_prepend()`.
///
/// The attach helpers below are reached from both builtins and only the diagnostic tells them
/// apart, so the flag is derived rather than threaded through every signature.
fn prepend_from_name(inst: &Instruction) -> bool {
    matches!(inst.immediate, Some(Immediate::Data(_))) && false
}

""",
    "",
)
open(p, 'w').write(s)
